INSERT INTO support.faq (id, step, question, answer, sort) VALUES
    ('f-1',  'PRODUCT',     'Как выбрать подходящий кредит?', 'Откройте «Подбор по задаче»: укажите цель, сумму и срок — каталог подсветит подходящие продукты и объяснит, почему другие не подходят.', 1),
    ('f-2',  'PRODUCT',     'Платёж в калькуляторе окончательный?', 'Нет. До проверки банк не знает вашу ставку, поэтому калькулятор показывает диапазон платежа по ставкам продукта. Точный платёж будет в предложении банка.', 2),
    ('f-3',  'PRODUCT',     'Кредит доступен только клиентам банка?', 'Кабинетом пользуются действующие клиенты банка, поэтому все продукты каталога вам доступны.', 3),
    ('f-4',  'APPLICATION', 'Нужно ли загружать документы или выписки?', 'Нет. Данные о компании, руководителе, учредителях и оборотах банк берёт из ваших счетов и государственных реестров.', 1),
    ('f-5',  'APPLICATION', 'Кто может подать заявку от имени компании?', 'Руководитель или представитель с действующей машиночитаемой доверенностью (МЧД), известной банку. Номер МЧД вводить не нужно.', 2),
    ('f-6',  'APPLICATION', 'Зачем согласие на запрос в БКИ?', 'Без него банк не может узнать кредитную историю и дать предварительное решение. Для ООО нужно ещё согласие поручителя.', 3),
    ('f-7',  'APPLICATION', 'Можно ли продолжить заявку позже?', 'Да. Заявка сохраняется автоматически и остаётся в «Моих заявках» как черновик.', 4),
    ('f-8',  'APPLICATION', 'В заявке устаревший адрес или реквизиты. Что делать?', 'Данные компании в заявке — из банка, в заявке они не меняются. Обновите их в банке через обращение в поддержку, и в заявке они станут новыми.', 5),
    ('f-9',  'DOCUMENTS',   'Какие документы нужно подписать?', 'Кредитный договор, а для ООО — ещё договор поручительства. Банк формирует их сам по условиям принятого предложения.', 1),
    ('f-10', 'DOCUMENTS',   'Как подписать договор?', 'На странице подписания проверьте условия и подтвердите подпись. После подписи банк выдаст кредит.', 2),
    ('f-11', 'STATUS',      'Как узнать статус заявки?', 'Статус, что сейчас происходит и что делать дальше показаны в карточке заявки. О важных изменениях придёт уведомление в кабинете.', 1),
    ('f-12', 'STATUS',      'Банк запросил информацию. Что делать?', 'Откройте заявку и ответьте на вопросы банка. После ответа заявка вернётся на проверку.', 2),
    ('f-13', 'DECISION',    'Что означает «Иные условия»?', 'Банк готов выдать кредит, но с другой суммой, сроком или ставкой. Сравните предложенные условия с запрошенными и примите или отклоните их.', 1),
    ('f-14', 'DECISION',    'Банк отказал. Что дальше?', 'В карточке заявки указаны причина и другие продукты, которые можно оформить. Новую заявку можно подать в любой момент.', 2),
    ('f-15', 'DECISION',    'Где найти график платежей?', 'После выдачи кредита график — в разделе «Мои кредиты», ближайшие платежи — в платёжном календаре.', 3);
